def agent_action(sandbox, agent_body, step_count):
    # Get current position and velocity
    pos = sandbox.get_sled_position()
    vel = sandbox.get_sled_velocity()

    # Check if checkpoints are reached
    if sandbox.get_checkpoint_a_reached():
        next_checkpoint = 'Beta'
    elif sandbox.get_checkpoint_b_reached():
        next_checkpoint = 'Target'
    else:
        next_checkpoint = 'Alpha'

    # Determine target position for next checkpoint
    if next_checkpoint == 'Alpha':
        target_x = 18.25  # Center of Alpha zone
        target_y = 4.15
    elif next_checkpoint == 'Beta':
        target_x = 23.75  # Center of Beta zone
        target_y = 2.85
    else:
        target_x = 28.0  # Center of target zone
        target_y = 2.5

    # Calculate direction to target
    dx = target_x - pos[0]
    dy = target_y - pos[1]
    distance = math.sqrt(dx**2 + dy**2)

    # If very close, no thrust needed
    if distance < 0.1:
        sandbox.apply_thrust(0, 0)
        return

    # Determine thrust magnitude based on distance
    if distance > 5.0:
        thrust_mag = 15.0  # High thrust for long distance
    elif distance > 2.0:
        thrust_mag = 10.0  # Moderate thrust for mid-distance
    else:
        thrust_mag = 5.0  # Low thrust for close approach

    # Adjust thrust if near checkpoint zone
    if next_checkpoint == 'Alpha':
        if 17.5 <= pos[0] <= 19.0 and 3.8 <= pos[1] <= 4.5:
            thrust_mag = 3.0  # Reduce thrust to pass through checkpoint
    elif next_checkpoint == 'Beta':
        if 23.0 <= pos[0] <= 24.5 and 2.5 <= pos[1] <= 3.2:
            thrust_mag = 3.0  # Reduce thrust to pass through checkpoint
    elif next_checkpoint == 'Target':
        if 28 <= pos[0] <= 32 and 2.2 <= pos[1] <= 2.8:
            thrust_mag = 0.0  # Stop at target zone

    # Calculate direction vector
    direction_x = dx / distance
    direction_y = dy / distance

    # Apply thrust in the direction of the target
    sandbox.apply_thrust(direction_x * thrust_mag, direction_y * thrust_mag)
